/** Interpretive close-up evidence displays for Season 1 V4 episodes 21–24. */
import {restoreArc2124} from './arc2124.mjs';
const NS='http://www.w3.org/2000/svg';
const e=(tag,cls)=>{let n=document.createElement(tag);if(cls)n.className=cls;return n;};
function svg(label){let s=document.createElementNS(NS,'svg');s.setAttribute('viewBox','0 0 360 150');s.setAttribute('role','img');s.setAttribute('aria-label',label);s.style.cssText='width:100%;max-height:145px;background:#071d2b;border-radius:.5rem';return s;}
function path(p,tag,a){let n=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(a))n.setAttribute(k,String(v));p.append(n);return n;}
function wrap(label){let n=e('section','arc2124-visual');n.setAttribute('aria-label',label);n.style.cssText='margin:.6rem 0;padding:.5rem;border:1px solid #70949a;border-radius:.7rem;background:#071d2b';return n;}
function caption(w,t){let p=e('p');p.style.cssText='margin:.35rem;color:#c9dddb;font-size:.85rem';p.textContent=t;w.append(p);}
function button(w,t,fn){let b=e('button','secondary');b.type='button';b.textContent=t;b.style.cssText='margin:.25rem;min-height:48px';b.onclick=fn;w.append(b);}
function evidence(s,dispatch){let w=wrap('Vault records compared with altered technology');let p=svg('Two evidence panels: original builders’ records and the altered city grid');path(p,'rect',{x:20,y:20,width:135,height:110,rx:6,fill:'#bfae89',stroke:'#dec28a','stroke-width':3});for(let y=42;y<110;y+=16)path(p,'path',{d:`M38 ${y}h95`,stroke:'#584e3b','stroke-width':3,opacity:s.flags.vault?.9:.2});path(p,'circle',{cx:260,cy:75,r:50,fill:'none',stroke:'#b69a67','stroke-width':3});for(let i=0;i<4;i++){let a=i*Math.PI/2;path(p,'path',{d:`M260 75 L${260+50*Math.cos(a)} ${75+50*Math.sin(a)}`,stroke:s.flags.altered?'#7bdae4':'#395963','stroke-width':4});}w.append(p);caption(w,`${s.flags.vault?'Vault records examined':'Vault records not yet examined'} · ${s.flags.altered?'Altered systems examined':'Altered systems not yet examined'}. Either strand can be compared with the claim; the other remains available.`);button(w,'Compare family archive ledger',()=>dispatch({type:'interact',id:'evidence-table',choice:'archive'}));button(w,'Compare ceremony schedule',()=>dispatch({type:'interact',id:'evidence-table',choice:'schedule'}));button(w,'Compare supply diagram',()=>dispatch({type:'interact',id:'evidence-table',choice:'supply'}));button(w,'Compare celestial chart',()=>dispatch({type:'interact',id:'evidence-table',choice:'stars'}));return w;}
function distribution(s,dispatch){let w=wrap('Distribution route model'),p=svg('A model of center, inner ring, and outer ring with a selectable channel');const supplied=s.distribution==='outer';const nodes=[80,180,280];for(let i=0;i<3;i++)path(p,'circle',{cx:nodes[i],cy:75,r:26,fill:supplied&&(i!==1||s.route==='linked')&&s.route?'#176975':'#18303a',stroke:'#b99b64','stroke-width':3});if(s.route==='linked'){path(p,'path',{d:'M106 75 H154 M206 75 H254',stroke:'#77dce5','stroke-width':5});}else if(s.route==='bypass'){path(p,'path',{d:'M80 49 Q180 0 280 49',fill:'none',stroke:'#77dce5','stroke-width':5});}else path(p,'path',{d:'M106 75 H154 M206 75 H254',stroke:'#49676b','stroke-width':3,'stroke-dasharray':'5 6'});w.append(p);caption(w,!supplied?'Deliver the crystal to the outer station before testing a route.':!s.route?'Choose a route and trace its response.':s.route==='bypass'?'The outer and center respond; the inner ring remains dark.':'All three rings respond through the connected route.');button(w,'Route around the inner ring',()=>dispatch({type:'interact',id:'distribution',choice:'bypass'}));button(w,'Route through the inner ring',()=>dispatch({type:'interact',id:'distribution',choice:'linked'}));button(w,'Trace the channel response',()=>dispatch({type:'interact',id:'distribution',choice:'observe'}));return w;}
export function makeArc2124Visual(sceneId,objectId,state,dispatch){if(typeof dispatch!=='function')throw new TypeError('dispatch callback required');const s=restoreArc2124(state?.state??state);if(sceneId==='truth-power'&&objectId==='evidence-table')return evidence(s,dispatch);if(sceneId==='awakening'&&objectId==='distribution')return distribution(s,dispatch);return null;}
